<?php require '../includes/functions.php';if(user()){header('Location: '.url('app.php'));exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=$pdo->prepare('SELECT * FROM users WHERE email=? AND active=1');$st->execute([trim($_POST['email']??'')]);$u=$st->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];$pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$u['id']]);header('Location: '.url('app.php'));exit;}$err='Correo o contraseña incorrectos.';}$title='Ingresar';require '../includes/header.php';?><main class="auth-wrap"><form class="auth-card" method="post"><div class="auth-logo"><img src="<?=url('assets/img/logo.png')?>"></div><h1>Bienvenido</h1><p>Ingresa para reportar, buscar y ayudar.</p><?php if($err):?><div class="flash err"><?=e($err)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Correo electrónico</label><input class="input" type="email" name="email" required><label>Contraseña</label><input class="input" type="password" name="password" required><button class="btn primary" style="width:100%;margin-top:20px">Ingresar</button><p class="small">¿Aún no tienes cuenta? <a href="<?=url('auth/register.php')?>"><b>Crear cuenta</b></a></p></form></main><?php require '../includes/footer.php';?>